script:
var sys = create("system", { x: 0, y: 0, domain: "mechanics", width: 460, height: 500 });
var pivot = create("hinge", { x: 320, y: 100 });
var bob = create("mass", { x: 320, y: 340, mass: 1 });
connect(pivot.centre, bob.centre, "rod");
var lSlider = create("slider", { x: 60, y: 460, min: 50, max: 300, step: 10, value: 200, label: "Pendulum length (px)", targetParamName: "length" });
lSlider.set({ targetObjectId: bob, targetParamName: "y", expression: "pivot.y + lSlider.value / 2" });
graph.plot(bob.swing);

var sys = create("system", { x: 0, y: 0, domain: "mechanics", width: 460, height: 500 });
var anchor = create("ground", { x: 230, y: 80, width: 100 });
var block = create("mass", { x: 230, y: 320, mass: 2 });
var spring = create("spring", { length: 220, k: 50 });
var damper = create("damper", { dampingCoefficient: 10 });
connect(anchor.centre, block.centre, "rod");
connect(spring.a, anchor.centre);
connect(spring.b, block.centre);
connect(damper.a, spring.b);
connect(damper.b, block.centre);
var kSlider = create("slider", { x: 60, y: 420, min: 10, max: 150, step: 10, value: 50, label: "Stiffness k (N/m)", targetParamName: "k", targetObjectId: spring });
var cSlider = create("slider", { x: 60, y: 460, min: 2, max: 30, step: 1, value: 10, label: "Damping c (Ns/m)", targetParamName: "dampingCoefficient", targetObjectId: damper });
graph.plot(block.y);

var sys = create("system", { x: 0, y: 0, domain: "mechanics", width: 900, height: 580 });
var floor = create("ground", { x: 20, y: 520, width: 860 });
var ball = create("mass", { x: 80, y: 480, mass: 1, vx: 8, vy: -8 });
graph.plot(ball.y, ball.x);

var sys = create("system", { x: 0, y: 0, domain: "mechanics", width: 460, height: 360 });
var floor = create("ground", { x: 20, y: 320, width: 760 });
var block = create("block", { x: 180, y: 200, mass: 5 });
var ramp = create("beam", { x: 200, y: 240, length: 200, angle: -30 });
connect(block.centre, ramp.centre, "rod");
block.set({ friction: 0.3 });

var sys = create("system", { x: 0, y: 0, domain: "mechanics", width: 460, height: 360 });
var m1 = create("mass", { mass: 2, x: 50, y: 180, name: "m1" });
var m2 = create("mass", { mass: 3, x: 350, y: 180, vx: -5, name: "m2" });
addproperty(m1, "rigidBody");
addproperty(m2, "rigidBody");
connect(m1.centre, m2.centre, "rod");

var rlc_sys = create("system", { x: 0, y: 0, domain: "electrical", width: 460, height: 360 });
var bat = create("battery", { V: 9 }, { parent: rlc_sys });
var r = create("resistor", { R: 1000 }, { parent: rlc_sys });
var l = create("inductor", { L: 0.1 }, { parent: rlc_sys });
var c = create("capacitor", { C: 1e-6 }, { parent: rlc_sys });
var vm = create("voltmeter", {}, { parent: rlc_sys });
connect(bat.positive, r.a);
connect(r.b, l.a);
connect(l.b, c.a);
connect(c.b, bat.negative);
connect(vm.a, r.b);
connect(vm.b, l.b);
graph.plot(rlc_sys.I);
